class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def supplyVaccine(root):
    def dfs(node):
        if not node:
            return 0, 0, 0
        l_no_need, l_need, l_has = dfs(node.left)
        r_no_need, r_need, r_has = dfs(node.right)
        no_need = l_has + r_has
        need = min(l_need + r_need, l_need + r_has, l_has + r_need)
        has = 1 + min(l_need, l_has) + min(r_need, r_has)
        return no_need, need, has
    return min(dfs(root)[1:])
